  1→/**
  2→ * Design System Token Contract Tests
  3→ *
  4→ * Validates that the web UI build output contains all required design system
  5→ * tokens as defined by the imgen token-contract.css specification.
  6→ *
  7→ * Tests read the built CSS output (packages/web-ui/build/), verifying the
  8→ * full Tailwind pipeline processes tokens correctly.
  9→ *
 10→ * Spec: @ui-design-system
 11→ */
 12→
 13→import { describe, it, expect, beforeAll } from "vitest";
 14→import { readdirSync, readFileSync, existsSync } from "node:fs";
 15→import { join } from "node:path";
 16→
 17→const WEB_UI_BUILD = join(process.cwd(), "packages", "web-ui", "build");
 18→const CSS_ASSETS_DIR = join(WEB_UI_BUILD, "_app", "immutable", "assets");
 19→
 20→let mainCss = "";
 21→
 22→beforeAll(() => {
 23→  if (!existsSync(CSS_ASSETS_DIR)) {
 24→    throw new Error(
 25→      `Build output not found at ${CSS_ASSETS_DIR}. Run "npm run build" in packages/web-ui/ first.`,
 26→    );
 27→  }
 28→
 29→  const cssFiles = readdirSync(CSS_ASSETS_DIR).filter((f) =>
 30→    f.endsWith(".css"),
 31→  );
 32→  mainCss = cssFiles
 33→    .map((f) => readFileSync(join(CSS_ASSETS_DIR, f), "utf-8"))
 34→    .join("\n");
 35→});
 36→
 37→// AC: @ui-design-system ac-1
 38→describe("design system tokens (@ui-design-system ac-1)", () => {
 39→  describe("16 color tokens as CSS custom properties", () => {
 40→    const colorTokens = [
 41→      "design-bg",
 42→      "design-fg",
 43→      "design-card",
 44→      "design-card-fg",
 45→      "design-primary",
 46→      "design-primary-fg",
 47→      "design-secondary",
 48→      "design-secondary-fg",
 49→      "design-muted",
 50→      "design-muted-fg",
 51→      "design-accent",
 52→      "design-accent-fg",
 53→      "design-destructive",
 54→      "design-border",
 55→      "design-input",
 56→      "design-ring",
 57→    ];
 58→
 59→    it("includes all 16 design color token CSS custom properties", () => {
 60→      for (const token of colorTokens) {
 61→        expect(mainCss, `missing --${token}`).toContain(`--${token}`);
 62→      }
 63→    });
 64→
 65→    it("uses oklch color space for color token values", () => {
 66→      // Minified CSS may omit space after colon
 67→      expect(mainCss).toMatch(/--design-bg:\s*oklch\(/);
 68→      expect(mainCss).toMatch(/--design-fg:\s*oklch\(/);
 69→      expect(mainCss).toMatch(/--design-primary:\s*oklch\(/);
 70→      expect(mainCss).toMatch(/--design-destructive:\s*oklch\(/);
 71→    });
 72→  });
 73→
 74→  describe("4 radius tokens", () => {
 75→    it("includes all 4 design radius CSS custom properties", () => {
 76→      for (const suffix of ["sm", "md", "lg", "xl"]) {
 77→        expect(mainCss, `missing --design-radius-${suffix}`).toContain(
 78→          `--design-radius-${suffix}`,
 79→        );
 80→      }
 81→    });
 82→  });
 83→
 84→  describe("7 spacing tokens", () => {
 85→    it("includes all 7 design spacing CSS custom properties", () => {
 86→      for (const suffix of ["xs", "sm", "md", "lg", "xl", "2xl", "3xl"]) {
 87→        expect(mainCss, `missing --design-spacing-${suffix}`).toContain(
 88→          `--design-spacing-${suffix}`,
 89→        );
 90→      }
 91→    });
 92→  });
 93→
 94→  describe("7 z-index layers", () => {
 95→    it("includes all 7 design z-index CSS custom properties", () => {
 96→      for (const suffix of [
 97→        "base",
 98→        "dropdown",
 99→        "sticky",
100→        "overlay",
101→        "modal",
102→        "popover",
103→        "toast",
104→      ]) {
105→        expect(mainCss, `missing --design-z-${suffix}`).toContain(
106→          `--design-z-${suffix}`,
107→        );
108→      }
109→    });
110→  });
111→
112→  describe("3 font families", () => {
113→    it("includes design font family CSS custom properties", () => {
114→      expect(mainCss).toContain("--font-design-primary");
115→      expect(mainCss).toContain("--font-design-secondary");
116→      expect(mainCss).toContain("--font-design-mono");
117→    });
118→  });
119→
120→  it("Tailwind @theme inline maps design tokens to utility namespace", () => {
121→    // Tailwind v4 tree-shakes @theme inline mappings that aren't used by any
122→    // utility class in the codebase. The presence of --design-* custom properties
123→    // in the built CSS proves tokens.css was imported and processed. The @theme
124→    // inline block in app.css (verified by build success) makes these available
125→    // as utility classes (e.g. bg-design-bg, text-design-fg) — they appear in
126→    // built CSS only when a component uses them. This test verifies the token
127→    // contract is intact; actual utility usage is verified by component tests.
128→    expect(mainCss).toContain("--design-bg");
129→    expect(mainCss).toContain("--design-spacing-xs");
130→    expect(mainCss).toContain("--design-z-base");
131→    expect(mainCss).toContain("--font-design-primary");
132→  });
